CREATE TABLE IF NOT EXISTS monthly_sales_register (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    serial_no INTEGER NOT NULL,
    business_date TEXT NOT NULL,
    bill_no TEXT NOT NULL UNIQUE,
    room_no TEXT NOT NULL,
    rent REAL DEFAULT 0,
    cgst REAL DEFAULT 0,
    sgst REAL DEFAULT 0,
    misc REAL DEFAULT 0,
    laundry REAL DEFAULT 0,
    minibar REAL DEFAULT 0,
    room_service REAL DEFAULT 0,
    net_amount REAL DEFAULT 0,
    advance REAL DEFAULT 0,
    discount REAL DEFAULT 0,
    complimentary REAL DEFAULT 0,
    void_amt REAL DEFAULT 0,
    allowances REAL DEFAULT 0,
    paid_out REAL DEFAULT 0,
    cash REAL DEFAULT 0,
    btc REAL DEFAULT 0,
    cc REAL DEFAULT 0,
    online REAL DEFAULT 0,
    remark TEXT,
    guest_name TEXT NOT NULL,
    company TEXT,
    gstin TEXT,
    is_b2b INTEGER DEFAULT 0,
    state_code TEXT DEFAULT '21',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_monthly_sales_bill ON monthly_sales_register(bill_no);
CREATE INDEX IF NOT EXISTS idx_monthly_sales_date ON monthly_sales_register(business_date);
CREATE INDEX IF NOT EXISTS idx_monthly_sales_room ON monthly_sales_register(room_no);
CREATE INDEX IF NOT EXISTS idx_monthly_sales_gstin ON monthly_sales_register(gstin);

-- Seed all 223 June 2026 records
DELETE FROM monthly_sales_register WHERE business_date LIKE '2026-06%';
